export fn majority_element_sort(v:[*c]const i64,n:usize)i64{if(v==null or n<2 or n>128)return -1;var a:[128]i32=undefined;for(0..n)|i|{if(v[i]<-2147483648 or v[i]>2147483647)return -1;a[i]=@intCast(v[i]);}for(1..n)|i|{const x=a[i];var j=i;while(j>0 and a[j-1]>x){a[j]=a[j-1];j-=1;}a[j]=x;}var run:usize=1;for(1..n)|i|{if(a[i]==a[i-1])run+=1 else run=1;if(run>n/2)return a[i];}return -1;}
